'use strict';
const CobaltReportsUI={t:(cn,en)=>I18n.language==='en'?en:cn,base:'/cobalt/reports',labels:{"batches":["在库批次数","In-stock Batches"],"bags":["袋数","Bags"],"unconfirmed_bags":["未确认重量袋数","Unconfirmed Weight Bags"],"unlocated_bags":["未定位袋数","Unlocated Bags"],"expected_gross_kg":["预计毛重kg","Expected Gross kg"],"expected_net_kg":["预计净重kg","Expected Net kg"],"actual_gross_kg":["实际毛重kg","Actual Gross kg"],"actual_net_kg":["实际净重kg","Actual Net kg"],"confirmed_arecoms_mt":["已确认人工金属吨","Confirmed Manual Metal MT"],"arecoms_unconfirmed_batches":["金属量未确认批次数","Unconfirmed Metal Batches"],"preparing_batches":["备货作业中批次数","Preparing Batches"],"review_batches":["待完工审核批次数","Completion Review Batches"],"completed_batches":["备货完成未匹配批次数","Completed Unmatched Batches"],"matched_batches":["已匹配装车批次数（含装车中及待审）","Matched Batches (Including Loading / Review)"],"loaded_not_outbound_batches":["已装车未正式出库批次数","Loaded Not Outbound Batches"],"loaded_vehicles":["已审核装车车辆数","Approved Loaded Vehicles"],"departed_vehicles":["实际离场车辆数","Actual Departed Vehicles"],"outbound_vehicles":["正式出库车辆数","Formal Outbound Vehicles"],"outbound_batches":["正式出库批次数","Formal Outbound Batches"],"arecoms_mt":["人工ARECOMS金属吨","Manual ARECOMS Metal MT"],"planned_vehicles":["计划车辆数","Planned Vehicles"],"dispatched_vehicles":["已派车车辆数","Dispatched Vehicles"],"arrived_vehicles":["已到场车辆数","Arrived Vehicles"],"matched_vehicles":["有效匹配车辆数","Valid Matched Vehicles"],"planned_physical_mt":["计划实物吨","Planned Physical MT"],"planned_metal_mt":["计划预计金属吨","Planned Estimated Metal MT"],"execution_pct":["开票确认履约比例%","Invoice-confirmed Fulfilment %"],"archived_vehicles":["已归档车辆数","Archived Vehicles"],"missing_vehicles":["未归档车辆数","Missing Documents"]},fmt(v,kg=false){return v==null?this.t('未确认','Unconfirmed'):Number(kg?Number(v)/1000:v).toLocaleString(I18n.language==='en'?'en-US':'zh-CN',{minimumFractionDigits:4,maximumFractionDigits:4});},
 metrics(obj){return '<div class="co-report-metrics">'+Object.entries(obj).map(([k,v])=>{const weight=/_kg$/.test(k),metal=/_mt$/.test(k),name=this.labels[k]||[k,k];return '<div class="metric-card"><span>'+esc(this.t(...name))+(weight?' (MT)':'')+'</span><strong>'+esc(weight||metal?this.fmt(v,weight):v)+'</strong></div>';}).join('')+'</div>';},
 table(spec,rows,id){return CobaltSalesUI.table(spec.map(([k,cn,en])=>[cn,en]),rows.map(r=>'<tr>'+spec.map(([k,cn,en,type])=>'<td>'+(type==='link'?r[k]:type==='mt'?esc(this.fmt(r[k],true)):type==='metal'?esc(this.fmt(r[k])):esc(k==='packing_status'?this.t(r[k]==='ARCHIVED'?'已归档':'未归档',r[k]):k==='execution_pct'?this.fmt(r[k]):r[k]??'—'))+'</td>').join('')+'</tr>'),id);},
 error(e){const m={CO_REPORT_CHANGED:['数据已变化，请重新查询后导出。','Data changed. Refresh before exporting.'],CO_REPORT_DATE:['请选择有效且不超过十年的日期范围。','Select a valid date range within ten years.'],CO_REPORT_SCOPE:['筛选对象不在授权范围。','The selected record is outside your scope.'],CO_REPORT_FILTER:['筛选字段无效。','Invalid report filter.'],CO_REPORT_STATE:['业务状态无效。','Invalid business state.'],CO_REPORT_LIMIT:['明细超过10000行，请缩小范围。','More than 10,000 detail rows; narrow the filters.']};return m[e.message]?this.t(...m[e.message]):CobaltUI.error(e);},
 async route(){return Reports463.render();},
 group(rows,key,label,id){return this.table([[key,label,label],['vehicles','车辆数','Vehicles'],['bags','袋数','Bags'],['actual_net_kg','实际净重 MT','Actual Net MT','mt'],['arecoms_mt','人工ARECOMS MT','Manual ARECOMS MT','metal']],rows,id);},state(s){return this.t(({PREPARING:'备货作业中',PENDING_COMPLETION_REVIEW:'待完工审核',COMPLETED:'备货完成',MATCHED:'已匹配装车',LOADING:'实际装车中',REVIEW_PENDING:'待装车审核',LOADED:'已装车待离场',DEPARTED:'已离场待出库',OUTBOUND_PENDING:'待出库审核',LOGISTICS_APPROVED:'物流审核通过',OUTBOUND_CORRECTION:'出库退回修改',OUTBOUND:'正式出库'})[s]||s,s.replaceAll('_',' '));}};
const reportRoute=CobaltUI.route.bind(CobaltUI);CobaltUI.route=p=>p==='/reports'?CobaltReportsUI.route():reportRoute(p);const reportLanguage=CobaltUI.languageChanged.bind(CobaltUI);CobaltUI.languageChanged=()=>location.pathname==='/reports'?CobaltReportsUI.route():reportLanguage();const reportPermission=Router.permission.bind(Router);Router.permission=p=>!ProductContext.isCopper()&&AppConfig.cobaltReportsV441&&p==='/reports'?'report:read':reportPermission(p);
